import{_ as t,o,c as a,a0 as n}from"./chunks/framework.D4fUSYzX.js";const s="/my-little-software-factory/assets/decision-modal.CpPgzOGO.png",p=JSON.parse(`{"title":"Modals","description":"The decision modal's rows, the missing modal, the Ticket close, and the leftover environment fact.","frontmatter":{"title":"Modals","description":"The decision modal's rows, the missing modal, the Ticket close, and the leftover environment fact."},"headers":[],"relativePath":"operation/modals.md","filePath":"operation/modals.md"}`),i={name:"operation/modals.md"};function r(d,e,h,l,c,m){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="modals" tabindex="-1">Modals <a class="header-anchor" href="#modals" aria-label="Permalink to &quot;Modals&quot;">​</a></h1><h2 id="decision-modal" tabindex="-1">Decision modal <a class="header-anchor" href="#decision-modal" aria-label="Permalink to &quot;Decision modal&quot;">​</a></h2><p><img src="'+s+`" alt="The decision modal on an awaiting ticket: the turn log of the settled
turn above the choice rows"></p><p>Enter on an <code>awaiting</code> ticket opens the decision modal: the turn log of the settled turn above the choice rows, with the repository, task type, agent, and completion time named under the border. <code>Up</code> and <code>Down</code> move between the rows, <code>j</code> and <code>k</code> scroll the log, <code>Enter</code> chooses the selected row, <code>e</code> edits the selected Handoff row&#39;s settings before it starts, and <code>Esc</code> closes the modal: nothing runs, and the ticket stays awaiting.</p><p>The rows the modal offers:</p><ul><li><strong>Close</strong> ends the work cycle: the ticket returns to open, and the handoff&#39;s environment is closed without touching your git branch - the branch, the pushed work, and the pull requests are left behind.</li><li><strong>Goto</strong> focuses the agent&#39;s pane in herdr so you can steer it by hand. The ticket stays awaiting until the next poll moves it or you decide it.</li><li><strong>Handoff: <code>&lt;task type&gt;</code></strong> hands the ticket off to the next kind of work, when the settled turn&#39;s labels put it in a state that offers one. <code>e</code> on the row edits that one handoff first.</li><li><strong>Re-fire</strong> appears when the turn&#39;s transition did not complete its work - no branch held, or the label write failed. It runs the same transition again, reading the source as it stands now.</li></ul><p>In auto mode the factory decides the settled turn itself: Enter only reports what it decided, and the modal stays closed. In manual mode the modal opens on every settled turn (ADR 0092), and when the turn&#39;s Next step stands under a gate - the position offers no task, the position is not actionable, the Same-type hold, or the Handoff limit - the screen states the hold beside the row you can still confirm.</p><h2 id="missing-modal" tabindex="-1">Missing modal <a class="header-anchor" href="#missing-modal" aria-label="Permalink to &quot;Missing modal&quot;">​</a></h2><p>Enter on a ticket whose agent is missing opens the missing modal. It shows the badge fact and the handoff attempt count, and it offers two rows:</p><ul><li><strong>Restart</strong> hands the ticket off again with the same choices, in the workspace the handoff recorded, and the last message as the previous message.</li><li><strong>Abandon</strong> ends the work cycle: the ticket returns to open, the environment is closed, and the missing badge clears.</li></ul><h2 id="ticket-close" tabindex="-1">Ticket close <a class="header-anchor" href="#ticket-close" aria-label="Permalink to &quot;Ticket close&quot;">​</a></h2><p>Key <code>w</code> in either Ticket pane ends the work cycle of the selected ticket, behind a confirmation that names what is alive and what survives. A close leaves the git branch, the pushed commits, and the pull requests behind: it takes only the environment the handoff built, and it never moves your view in herdr. The ticket returns to open, and the ended cycle counts toward the ticket&#39;s handoff limit.</p><h2 id="leftover-environment" tabindex="-1">Leftover environment <a class="header-anchor" href="#leftover-environment" aria-label="Permalink to &quot;Leftover environment&quot;">​</a></h2><p>When herdr cannot remove an environment, the ticket wears a <code>leftover</code> marker and its detail names the workspace, tab, and pane that remain, with the reason and since when. The control plane keeps no clear of its own: the cleanup runs in herdr, not in the control plane, so go there to remove it.</p><h2 id="agent-name-held" tabindex="-1">Agent name held <a class="header-anchor" href="#agent-name-held" aria-label="Permalink to &quot;Agent name held&quot;">​</a></h2><p>When herdr refuses a handoff because a pane the plane cannot tie to that ticket holds the ticket&#39;s stable Agent name, the ticket wears a <code>name held</code> marker and its detail names the pane, the workspace, the name, and since when, with herdr&#39;s refusal behind it. The plane owns no cleanup for that pane, so close the Agent that holds the name in herdr and hand the ticket off yourself: that start clears the marker, and the automatic starts resume. While the marker stands the factory adds no automatic start for the ticket. See <a href="./../adr/0107-a-herdr-agent-name-held-by-a-stranger-is-a-fact-on-the-ticket-and-the-top-up-waits-for-the-operator.html">ADR 0107</a>.</p>`,16)])])}const u=t(i,[["render",r]]);export{p as __pageData,u as default};
